// https://stackoverflow.com/questions/53069040/checking-a-string-contains-only-ascii-characters
func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] > unicode.MaxASCII {
			return false
		}
	}
	return true
}

// escapeQuotes escapes the characters that are not allowed inside a quoted-string
// of an HTTP header value, as defined in RFC 2616 / RFC 7230 (quoted-pair).
func escapeQuotes(s string) string {
	var builder strings.Builder
	builder.Grow(len(s))
	for i := 0; i < len(s); i++ {
		if c := s[i]; c == '\\' || c == '"' {
			builder.WriteByte('\\')
		}
		builder.WriteByte(s[i])
	}
	return builder.String()
}

